import {FABRIC_MODEL,WORKLOADS,simulateFabric,compactFabric} from './fabric.mjs';
export const COLS=16, ROWS=12;
export const MODULES={
 shader:{name:'流式多处理器',short:'SM',desc:'GPU 的计算核心，提升图形性能',w:2,h:2,color:'#46d5b1',price:28,power:7,area:12},
 tensor:{name:'张量核心',short:'TC',desc:'加速 AI 运算与深度学习',w:2,h:2,color:'#ac8bf3',price:45,power:9,area:10},
 rt:{name:'光追核心',short:'RT',desc:'实时光线追踪，打造逼真画面',w:2,h:2,color:'#f4b972',price:40,power:8,area:10},
 cache:{name:'L2 高速缓存',short:'L2',desc:'减少数据等待，释放计算潜力',w:2,h:4,color:'#66b3ef',price:35,power:5,area:16},
 memory:{name:'显存控制器',short:'MC',desc:'连接 GDDR 显存，增加带宽',w:4,h:1,color:'#e39fbf',price:30,power:5,area:8},
 command:{name:'指令处理器',short:'CP',desc:'调度任务；芯片至少需要一个',w:2,h:2,color:'#82939d',price:20,power:4,area:10}
};
export const PROCESSES=[{nm:12,name:'12 nm',cost:0,scale:1,eff:1},{nm:7,name:'7 nm',cost:180,scale:.75,eff:.74},{nm:5,name:'5 nm',cost:350,scale:.58,eff:.54},{nm:3,name:'3 nm',cost:600,scale:.44,eff:.40}];
export const CONTRACTS=[
 {name:'点亮第一块芯片',client:'NOVA LABS',desc:'设计一颗均衡的入门 GPU，为独立游戏工作室提供动力。',score:4200,power:180,reward:260000,rp:90},
 {name:'光影之间',client:'LUMEN STUDIO',desc:'为实时渲染工作站设计 GPU，至少搭载 4 个光追核心。',score:5000,power:210,rt:4,reward:420000,rp:130},
 {name:'智能的下一步',client:'VECTOR AI',desc:'为 AI 推理平台设计芯片，至少搭载 6 个张量核心。',score:5600,power:220,tensor:6,reward:600000,rp:180},
 {name:'每一瓦都算数',client:'ORBIT SYSTEMS',desc:'使用 7 nm 或更先进工艺，在 150 W 内突破性能极限。',score:6500,power:150,nm:7,reward:800000,rp:220},
 {name:'旗舰诞生',client:'SILICON ALLIANCE',desc:'用 5 nm 或更先进工艺，打造一颗得分超过 9,000 的旗舰 GPU。',score:9000,power:240,nm:5,reward:1200000,rp:350}
];
export function freshState(){let i=0;const blocks=[];const add=(type,x,y)=>blocks.push({id:++i,type,x,y,rot:false});[1,5,9].forEach(x=>add('memory',x,0));[2,4,6].forEach(y=>[1,3,11,13].forEach(x=>add('shader',x,y)));add('cache',6,2);add('cache',8,2);add('command',7,7);[1,3].forEach(x=>add('rt',x,9));[11,13].forEach(x=>add('tensor',x,9));return{version:1,name:'NOVA-01',blocks,nextId:i+1,process:12,clock:1500,cash:2400000,rp:120,unlocked:[12],contract:0,runs:[],completed:[],totalRuns:0,sound:false,workload:'balanced',fabricLayer:'congestion',economy:freshEconomy()};}
export function size(block){const m=MODULES[block.type];return block.rot?{w:m.h,h:m.w}:{w:m.w,h:m.h};}
export function clusteredDesign(){let id=0;const blocks=[];const add=(type,x,y)=>blocks.push({id:++id,type,x,y,rot:false});for(const [ox,oy]of [[0,0],[8,0],[0,6],[8,6]]){add('cache',ox+3,oy+1);for(const [x,y]of [[1,1],[5,1],[1,3],[5,3]])add('shader',ox+x,oy+y);add('memory',ox+2,oy);}add('command',7,4);add('tensor',7,0);add('tensor',7,8);add('rt',0,5);add('rt',14,5);return {blocks,nextId:id+1};}
export function canPlace(state,type,x,y,rot=false,ignoreId=null){if(!MODULES[type])return false;const s=size({type,rot});if(!Number.isInteger(x)||!Number.isInteger(y)||x<0||y<0||x+s.w>COLS||y+s.h>ROWS)return false;return !state.blocks.some(b=>{if(b.id===ignoreId)return false;const z=size(b);return x<b.x+z.w&&x+s.w>b.x&&y<b.y+z.h&&y+s.h>b.y;});}
export function addBlock(state,type,x,y,rot=false){if(!canPlace(state,type,x,y,rot))return false;state.blocks.push({id:state.nextId++,type,x,y,rot});return true;}
export function metrics(state){
 const n=Object.fromEntries(Object.keys(MODULES).map(k=>[k,state.blocks.filter(b=>b.type===k).length]));
 const p=PROCESSES.find(p=>p.nm===state.process)||PROCESSES[0],freq=state.clock/1500;
 const balance=Math.min(1,n.memory/Math.max(1,n.shader/5))*Math.min(1,.65+n.cache*.175);
 const theoreticalTf=+(n.shader*.64*freq*balance*(1+(12-p.nm)*.012)).toFixed(2);
 const fabric=simulateFabric(state.blocks,MODULES,{clock:state.clock,workload:state.workload??'balanced'});
 const tf=+(theoreticalTf*fabric.classes.shader).toFixed(2),ai=+(n.tensor*4.8*freq*fabric.classes.tensor).toFixed(1),rt=+(n.rt*7.5*freq*fabric.classes.rt).toFixed(1);
 const networkPower=Math.round(fabric.wirePower*p.eff);
 const power=Math.round((state.blocks.reduce((a,b)=>a+MODULES[b.type].power,0)*Math.pow(freq,1.65)+18)*p.eff)+networkPower;
 const area=Math.round(state.blocks.reduce((a,b)=>a+MODULES[b.type].area,0)*p.scale);
 const cost=Math.round(state.blocks.reduce((a,b)=>a+MODULES[b.type].price,0)*(1+(12-p.nm)*.032));
 const rawBandwidth=n.memory*128,bandwidth=Math.round(rawBandwidth*fabric.efficiency);
 const occupied=state.blocks.reduce((a,b)=>{const s=size(b);return a+s.w*s.h;},0);
 const score=Math.round((tf*625+ai*38+rt*23)*(n.command?1:0)*(area<=600?1:.7));
 const rawScore=Math.round((theoreticalTf*625+n.tensor*4.8*freq*38+n.rt*7.5*freq*23)*(n.command?1:0)*(area<=600?1:.7));
 return{n,tf,ai,rt,theoreticalTf,rawScore,networkPower,fabric,power,area,cost,rawBandwidth,bandwidth,score,occupied,utilization:Math.round(occupied/(COLS*ROWS)*100),balance,valid:!!n.command&&!!n.shader&&!!n.memory&&power<=300&&area<=600};
}
export function contractReady(state,m=metrics(state)){const c=CONTRACTS[state.contract];return !!c&&m.valid&&m.score>=c.score&&m.power<=c.power&&(!c.rt||m.n.rt>=c.rt)&&(!c.tensor||m.n.tensor>=c.tensor)&&(!c.nm||state.process<=c.nm);}
export function designKey(state){return JSON.stringify({model:FABRIC_MODEL,blocks:state.blocks.map(({type,x,y,rot})=>({type,x,y,rot:!!rot})).sort((a,b)=>a.type.localeCompare(b.type)||a.x-b.x||a.y-b.y||Number(a.rot)-Number(b.rot)),process:state.process,clock:state.clock,workload:state.workload??'balanced'});}
export function benchmark(state){const m=metrics(state);if(!m.valid)return{error:!m.n.command?'请先添加指令处理器':!m.n.shader?'请至少添加一个流式多处理器':!m.n.memory?'请添加显存控制器':m.power>300?'功耗超过 300 W，请降低频率或升级工艺':'芯片面积超过 600 mm²'};const key=designKey(state);const bonus=state.runs.some(r=>r.key===key)?0:15;const result={...m,fabric:compactFabric(m.fabric),id:Date.now(),name:state.name,process:state.process,clock:state.clock,key,date:new Date().toISOString(),paid:false,bonus};state.rp+=bonus;state.runs.unshift(result);state.runs=state.runs.slice(0,30);state.totalRuns++;return result;}
export function deliver(state){const run=state.runs[0];if(!run||run.key!==designKey(state))return{error:'请先对当前设计运行基准测试'};if(!contractReady(state))return{error:'当前设计尚未满足订单要求'};if(run.paid)return{error:'本次测试已交付，请重新测试下一份订单'};const c=CONTRACTS[state.contract];run.paid=true;state.cash+=c.reward;state.rp+=c.rp;state.completed.push({name:c.name,score:run.score});state.contract++;return c;}
export function unlock(state,nm){const p=PROCESSES.find(p=>p.nm===nm);if(!p||state.unlocked.includes(nm))return false;const index=PROCESSES.indexOf(p);if(!state.unlocked.includes(PROCESSES[index-1].nm)||state.rp<p.cost)return false;state.rp-=p.cost;state.unlocked.push(nm);return true;}
export function restore(value){try{const s=JSON.parse(value);if(s.version!==1||!Array.isArray(s.blocks)||!PROCESSES.some(p=>p.nm===s.process)||!Array.isArray(s.unlocked)||!s.unlocked.includes(s.process)||!Number.isFinite(s.clock)||s.clock<900||s.clock>2400||!Number.isFinite(s.cash)||!Number.isFinite(s.rp)||!Number.isInteger(s.contract)||s.contract<0||s.contract>CONTRACTS.length||!Array.isArray(s.runs)||!Array.isArray(s.completed))return null;const tmp={...s,blocks:[]};for(const b of s.blocks){if(!canPlace(tmp,b.type,b.x,b.y,b.rot))return null;tmp.blocks.push(b);}s.nextId=Math.max(0,...s.blocks.map(b=>b.id))+1;s.workload=WORKLOADS[s.workload]?s.workload:'balanced';s.fabricLayer=['off','routes','congestion'].includes(s.fabricLayer)?s.fabricLayer:'congestion';if(s.economy===undefined)s.economy=freshEconomy();else if(!validEconomy(s.economy))return null;return s;}catch{return null;}}

export const PACKAGING={budget:{name:'精简封装',cost:35,returns:.035,appeal:.94},standard:{name:'标准封装',cost:75,returns:.01,appeal:1},premium:{name:'高端封装',cost:140,returns:.003,appeal:1.08}};
export const MARKETS={gaming:{name:'游戏玩家',base:380,capacity:1000},creator:{name:'创作工作站',base:240,capacity:650},ai:{name:'AI 推理',base:300,capacity:800}};
export const FACTORY_UPGRADES=[180000,360000,700000];
export const LAUNCH_COST=80000;
export function freshEconomy(){return {week:1,nextId:1,activeId:null,products:[],queue:[],reports:[],factoryLevel:0,revenue:0,costSold:0,fees:0,returns:0,storage:0,launchSpent:0,productionSpent:0,researchSpent:0,factorySpent:0,totalSold:0};}
export function inventory(product){return product.lots.reduce((n,l)=>n+l.units,0);}
export function businessSummary(state){const e=state.economy;return {profit:e.revenue-e.costSold-e.fees-e.returns-e.storage-e.launchSpent,stock:e.products.reduce((n,p)=>n+inventory(p),0),pending:e.queue.reduce((n,b)=>n+b.goodUnits,0),sold:e.totalSold,revenue:e.revenue,capacity:5000+e.factoryLevel*1500,bookValue:e.products.reduce((n,p)=>n+p.lots.reduce((a,l)=>a+l.cost,0),0)};}
export function marketReference(product,market=product.market){const m=product.spec;const base=market==='ai'?700+m.ai*40+m.tf*35:market==='creator'?600+m.tf*90+m.rt*12+m.bandwidth*.25:500+m.tf*100+m.rt*8;return Math.round(base*Math.min(1.12,Math.max(.8,1+(160-m.power)/900))/10)*10;}
function marketLots(state,product){return [...product.lots,...state.economy.queue.filter(b=>b.productId===product.id&&b.readyWeek<=state.economy.week+1).map(b=>({units:b.goodUnits,cost:b.total,packaging:b.packaging}))];}
function availableUnits(state,product){return marketLots(state,product).reduce((n,l)=>n+l.units,0);}
export function demandFor(state,product,price=product.price,market=product.market){if(!Number.isFinite(price)||price<100||!MARKETS[market])return 0;const reference=marketReference(product,market),ratio=price/reference;if(ratio>=3)return 0;const season=[1,1.12,.94,1.04,.88,1.08][(state.economy.week-1)%6];const lots=marketLots(state,product),stock=lots.reduce((s,l)=>s+l.units,0);const quality=stock?lots.reduce((s,l)=>s+l.units*PACKAGING[l.packaging].appeal,0)/stock:1;return Math.max(0,Math.floor(MARKETS[market].base*season*quality*Math.min(3,Math.pow(1/ratio,1.6)*(3-ratio)/2)));}
export function productionQuote(state,product,quantity=300,packaging='standard'){if(!product||!Number.isInteger(quantity)||quantity<100||quantity>5000||!PACKAGING[packaging])return {error:'批次数量需为 100–5,000 片整数，并选择有效封装方案'};const level=state.economy.factoryLevel;const yieldRate=Math.max(.65,Math.min(.98,.97-product.spec.area/4000-(12-product.process)*.004+level*.012));const goodUnits=Math.floor(quantity*yieldRate+1e-8);const volumeDiscount=quantity>=3000?.84:quantity>=1000?.9:quantity>=300?.96:1;const fabrication=Math.round(quantity*product.spec.cost*volumeDiscount*(1-level*.05));const packagingCost=goodUnits*PACKAGING[packaging].cost,testing=goodUnits*15,setup=20000;const total=fabrication+packagingCost+testing+setup;return {quantity,packaging,yieldRate,goodUnits,fabrication,packagingCost,testing,setup,total,unitCost:total/goodUnits,volumeDiscount,capacity:5000+level*1500};}
export function launchProduct(state){const key=designKey(state);if(!metrics(state).valid||!state.runs.some(r=>r.key===key))return {error:'请先对当前架构完成基准测试，再立项量产'};const existing=state.economy.products.find(p=>p.key===key);if(existing)return {error:'该架构已立项，请选择已有产品线',existingId:existing.id};if(state.cash<LAUNCH_COST)return {error:'立项需要 ¥ 80,000，请先筹措资金'};const e=state.economy;const p={id:e.nextId++,name:state.name,key,process:state.process,clock:state.clock,spec:JSON.parse(JSON.stringify({...metrics(state),fabric:compactFabric(metrics(state).fabric)})),market:'gaming',price:0,batchQuantity:300,batchPackaging:'standard',lots:[],sold:0,revenue:0,launchedWeek:e.week};p.price=marketReference(p);state.cash-=LAUNCH_COST;e.launchSpent+=LAUNCH_COST;e.products.push(p);e.activeId=p.id;return p;}
export function queueProduction(state,id,quantity,packaging){const e=state.economy,p=e.products.find(p=>p.id===id),q=productionQuote(state,p,quantity,packaging);if(q.error)return q;if(e.queue.reduce((n,b)=>n+b.quantity,0)+quantity>q.capacity)return {error:'本周排产已超过产能，请推进一周或升级产线'};if(state.cash<q.total)return {error:'资金不足，无法支付本批次生产费用'};state.cash-=q.total;e.productionSpent+=q.total;const batch={...q,id:e.nextId++,productId:id,readyWeek:e.week+1};e.queue.push(batch);return batch;}
export function setProductPricing(state,id,price,market){const p=state.economy.products.find(p=>p.id===id);if(!p||!Number.isInteger(price)||price<100||price>100000||!MARKETS[market])return {error:'售价需为 ¥ 100–100,000 之间的整数，并选择有效市场'};p.price=price;p.market=market;return p;}
export function fundResearch(state,amount){if(![50000,100000,250000,500000].includes(amount))return {error:'请选择有效研发预算'};if(state.cash<amount)return {error:'可用资金不足，先销售库存或交付订单赚取资金'};state.cash-=amount;state.rp+=amount/1000;state.economy.researchSpent+=amount;return {amount,rp:amount/1000};}
export function upgradeFactory(state){const e=state.economy,cost=FACTORY_UPGRADES[e.factoryLevel];if(!cost)return {error:'产线已达到最高等级'};if(state.cash<cost)return {error:'资金不足，无法升级产线'};state.cash-=cost;e.factorySpent+=cost;e.factoryLevel++;return {level:e.factoryLevel,cost};}
export function salesForecast(state,product,price=product.price,market=product.market){if(!MARKETS[market])return 0;const wanted=demandFor(state,product,price,market),available=availableUnits(state,product);const ownDemand=state.economy.products.filter(p=>p.id!==product.id&&p.market===market).reduce((n,p)=>n+Math.min(availableUnits(state,p),demandFor(state,p)),0);const allocation=Math.min(1,MARKETS[market].capacity/Math.max(1,ownDemand+Math.min(available,wanted)));return Math.floor((available?Math.min(available,wanted):wanted)*allocation);}
export function advanceBusinessWeek(state){const e=state.economy,week=e.week;const report={week,sold:0,revenue:0,costSold:0,fees:0,returns:0,storage:0,profit:0,arrived:0,products:[]};const due=e.queue.filter(b=>b.readyWeek<=week+1);for(const b of due){const p=e.products.find(p=>p.id===b.productId);p.lots.push({units:b.goodUnits,cost:b.total,packaging:b.packaging});report.arrived+=b.goodUnits;}e.queue=e.queue.filter(b=>b.readyWeek>week+1);const desired=new Map(e.products.map(p=>[p.id,Math.min(inventory(p),demandFor(state,p))]));const marketTotals=Object.fromEntries(Object.keys(MARKETS).map(k=>[k,e.products.filter(p=>p.market===k).reduce((n,p)=>n+desired.get(p.id),0)]));for(const p of e.products){const sold=Math.floor(desired.get(p.id)*Math.min(1,MARKETS[p.market].capacity/Math.max(1,marketTotals[p.market])));let remaining=sold,cost=0,returns=0;for(const lot of p.lots){if(!remaining)break;const count=Math.min(remaining,lot.units),allocated=count===lot.units?lot.cost:Math.floor(lot.cost*count/lot.units);cost+=allocated;returns+=Math.round(count*p.price*PACKAGING[lot.packaging].returns);lot.cost-=allocated;lot.units-=count;remaining-=count;}p.lots=p.lots.filter(l=>l.units>0);const revenue=sold*p.price,fees=Math.round(revenue*.04),storage=inventory(p);p.sold+=sold;p.revenue+=revenue;report.sold+=sold;report.revenue+=revenue;report.costSold+=cost;report.fees+=fees;report.returns+=returns;report.storage+=storage;if(sold||storage)report.products.push({id:p.id,name:p.name,sold,revenue,remaining:inventory(p)});}report.profit=report.revenue-report.costSold-report.fees-report.returns-report.storage;state.cash+=report.revenue-report.fees-report.returns-report.storage;for(const k of ['revenue','costSold','fees','returns','storage'])e[k]+=report[k];e.totalSold+=report.sold;e.week++;e.reports.unshift(report);e.reports=e.reports.slice(0,30);return report;}
function validEconomy(e){const nonnegative=n=>Number.isSafeInteger(n)&&n>=0;const keys=['revenue','costSold','fees','returns','storage','launchSpent','productionSpent','researchSpent','factorySpent','totalSold'];if(!e||!Number.isSafeInteger(e.week)||e.week<1||!Number.isSafeInteger(e.nextId)||e.nextId<1||!Number.isInteger(e.factoryLevel)||e.factoryLevel<0||e.factoryLevel>3||!keys.every(k=>nonnegative(e[k]))||!Array.isArray(e.products)||!Array.isArray(e.queue)||!Array.isArray(e.reports))return false;const ids=new Set();for(const p of e.products){if(!Number.isSafeInteger(p.id)||p.id<1||ids.has(p.id)||typeof p.name!=='string'||typeof p.key!=='string'||!PROCESSES.some(n=>n.nm===p.process)||!MARKETS[p.market]||!Number.isInteger(p.price)||p.price<100||p.price>100000||!p.spec||!['area','cost','score','tf','ai','rt','bandwidth','power'].every(k=>Number.isFinite(p.spec[k])&&p.spec[k]>=0)||!nonnegative(p.sold)||!nonnegative(p.revenue)||!Array.isArray(p.lots)||!p.lots.every(l=>Number.isSafeInteger(l.units)&&l.units>0&&nonnegative(l.cost)&&PACKAGING[l.packaging]))return false;ids.add(p.id);}if(e.activeId!==null&&!ids.has(e.activeId))return false;const batchIds=new Set(ids);for(const b of e.queue){if(!ids.has(b.productId)||!Number.isSafeInteger(b.id)||b.id<1||batchIds.has(b.id)||!Number.isInteger(b.quantity)||b.quantity<100||b.quantity>5000||!Number.isInteger(b.goodUnits)||b.goodUnits<=0||b.goodUnits>b.quantity||!nonnegative(b.total)||!PACKAGING[b.packaging]||!Number.isSafeInteger(b.readyWeek)||b.readyWeek<=e.week)return false;batchIds.add(b.id);}if([...batchIds].some(id=>id>=e.nextId))return false;return e.reports.every(r=>r&&['week','sold','revenue','costSold','fees','returns','storage','arrived'].every(k=>nonnegative(r[k]))&&Number.isSafeInteger(r.profit)&&Array.isArray(r.products)&&r.products.every(p=>typeof p.name==='string'&&nonnegative(p.sold)&&nonnegative(p.revenue)&&nonnegative(p.remaining)));}
